import{_ as e,c as r,o as i,ah as h}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"14、【大有】 乾下離上","description":"橫渠易說 - 14、【大有】 乾下離上","frontmatter":{"title":"14、【大有】 乾下離上","description":"橫渠易說 - 14、【大有】 乾下離上"},"headers":[],"relativePath":"classics/hengqu/016.md","filePath":"classics/hengqu/016.md"}'),l={name:"classics/hengqu/016.md"};function t(n,a,s,d,c,o){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="_14、【大有】-乾下離上" tabindex="-1">14、【大有】 乾下離上 <a class="header-anchor" href="#_14、【大有】-乾下離上" aria-label="Permalink to “14、【大有】 乾下離上”">​</a></h1><h3 id="彖曰-大有-柔得尊位-大中而上下應之曰大有。其德剛健而文明-應乎天而時行-是以元亨。" tabindex="-1">彖曰：大有，柔得尊位，大中而上下應之曰大有。其德剛健而文明，應乎天而時行，是以元亨。 <a class="header-anchor" href="#彖曰-大有-柔得尊位-大中而上下應之曰大有。其德剛健而文明-應乎天而時行-是以元亨。" aria-label="Permalink to “彖曰：大有，柔得尊位，大中而上下應之曰大有。其德剛健而文明，應乎天而時行，是以元亨。”">​</a></h3><p>柔得盛位，非所固有，故曰大有。 剛健故應乎天，文明故時行。</p><h3 id="象曰-火在天上-大有-君子以遏惡揚善-順天休命。" tabindex="-1">象曰：火在天上，大有，君子以遏惡揚善，順天休命。 <a class="header-anchor" href="#象曰-火在天上-大有-君子以遏惡揚善-順天休命。" aria-label="Permalink to “象曰：火在天上，大有，君子以遏惡揚善，順天休命。”">​</a></h3><p>柔能大有，非天道也，乃天命也，故曰“順天休命”。遏惡揚善，勉□也。</p><h3 id="初九-無交害-匪咎。艱則無咎。-象曰-大有初九-無交害也。" tabindex="-1">初九，無交害，匪咎。艱則無咎。 象曰：大有初九，無交害也。 <a class="header-anchor" href="#初九-無交害-匪咎。艱則無咎。-象曰-大有初九-無交害也。" aria-label="Permalink to “初九，無交害，匪咎。艱則無咎。 象曰：大有初九，無交害也。”">​</a></h3><p>二應於五，三能自通，四匪其旁，惟初無交故有害，然非其咎</p><h3 id="九二-大車以載-有攸往-無咎。-象曰-大車以載-積中不敗也。" tabindex="-1">九二，大車以載，有攸往，無咎。 象曰：“大車以載”，積中不敗也。 <a class="header-anchor" href="#九二-大車以載-有攸往-無咎。-象曰-大車以載-積中不敗也。" aria-label="Permalink to “九二，大車以載，有攸往，無咎。 象曰：“大車以載”，積中不敗也。”">​</a></h3><h3 id="九三-公用亨於天子-小人弗克。-象曰-公用亨於天子-小人害也。" tabindex="-1">九三，公用亨於天子，小人弗克。 象曰：“公用亨於天子”，小人害也。 <a class="header-anchor" href="#九三-公用亨於天子-小人弗克。-象曰-公用亨於天子-小人害也。" aria-label="Permalink to “九三，公用亨於天子，小人弗克。 象曰：“公用亨於天子”，小人害也。”">​</a></h3><p>非柔中文明之主不能察，非剛健不私之臣不能通，故曰“小人弗克”。</p><h3 id="九四-匪其彭-無咎。-象曰-匪其彭無咎-明辨晢也。" tabindex="-1">九四，匪其彭，無咎。 象曰：“匪其彭無咎”，明辨晢也。 <a class="header-anchor" href="#九四-匪其彭-無咎。-象曰-匪其彭無咎-明辨晢也。" aria-label="Permalink to “九四，匪其彭，無咎。 象曰：“匪其彭無咎”，明辨晢也。”">​</a></h3><h3 id="六五-厥孚交如威如-吉。-象曰-厥孚交如-信以發志也-威如之吉-易而無備也。" tabindex="-1">六五，厥孚交如威如，吉。 象曰：“厥孚交如”，信以發志也；威如之吉，易而無備也。 <a class="header-anchor" href="#六五-厥孚交如威如-吉。-象曰-厥孚交如-信以發志也-威如之吉-易而無備也。" aria-label="Permalink to “六五，厥孚交如威如，吉。 象曰：“厥孚交如”，信以發志也；威如之吉，易而無備也。”">​</a></h3><p>人威重有德望，則人自畏服，易曰“厥孚交如威如吉”，君子以至誠交人，然後有威重。“威如之吉，易而無備也”，君子至平易，有何關防擬備？惟以抑抑威儀為德之隅，儼然人望而畏之，既易而無備，則威如乃吉也。</p><h3 id="上九-自天祐之-吉無不利。-象曰-大有上吉-自天祐也。" tabindex="-1">上九，自天祐之，吉無不利。 象曰：大有上吉，自天祐也。 <a class="header-anchor" href="#上九-自天祐之-吉無不利。-象曰-大有上吉-自天祐也。" aria-label="Permalink to “上九，自天祐之，吉無不利。 象曰：大有上吉，自天祐也。”">​</a></h3><p>以剛而下柔，居上而志應於中，故曰履信思順，又以尚賢，蓋五陽一陰，又無物以間焉耳。剛柔相求，情也，信也。</p>',15)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
